const N:usize=8;const M:usize=12;const P:usize=8;const H:usize=56;const MAX_INPUT:usize=99;
struct G{n:usize,m:usize,p:usize,u:[usize;M],v:[usize;M],plen:[usize;P],path:[[usize;N];P]}
fn parse(a:&[i64])->Option<G>{if a.len()<3||a.len()>MAX_INPUT{return None}let(n0,m0,p0)=(a[0],a[1],a[2]);if n0<2||n0>N as i64||m0<1||m0>M as i64||p0<1||p0>P as i64{return None}let(n,m,p)=(n0 as usize,m0 as usize,p0 as usize);let mut pos=3;if pos+2*m>a.len(){return None}let(mut u,mut v)=([0usize;M],[0usize;M]);let mut seen=[[false;M];M];
 for e in 0..m{let(x0,y0)=(a[pos],a[pos+1]);pos+=2;if x0<0||x0 as usize>=n||y0<0||y0 as usize>=n||x0==y0{return None}let(x,y)=(x0 as usize,y0 as usize);let(lo,hi)=(x.min(y),x.max(y));if seen[lo][hi]{return None}seen[lo][hi]=true;u[e]=x;v[e]=y;}
 let(mut plen,mut path)=([0usize;P],[[0usize;N];P]);for q in 0..p{if pos+2>a.len(){return None}let start=a[pos];let k=a[pos+1];pos+=2;if start<0||start as usize>=n||k<1||k>=n as i64||pos+k as usize>a.len(){return None}plen[q]=k as usize;let mut cur=start as usize;let mut used_v=[false;N];let mut used_e=[false;M];used_v[cur]=true;for j in 0..plen[q]{let e0=a[pos];pos+=1;if e0<0||e0 as usize>=m{return None}let e=e0 as usize;if used_e[e]{return None}used_e[e]=true;path[q][j]=e;cur=if u[e]==cur{v[e]}else if v[e]==cur{u[e]}else{return None};if used_v[cur]{return None}used_v[cur]=true;}}
 if pos!=a.len(){return None}Some(G{n,m,p,u,v,plen,path})}
fn put(out:&mut[u8],words:&[i64]){for(i,w)in words.iter().enumerate(){out[i*8..i*8+8].copy_from_slice(&w.to_le_bytes())}}
#[no_mangle]
pub unsafe extern "C" fn packet_routing_work_conserving_schedule(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<3||length>MAX_INPUT{return -1}let a=std::slice::from_raw_parts(input,length);let g=match parse(a){Some(g)=>g,None=>return -1};let mut pos=[0usize;P];let(mut tt,mut te,mut tp)=([0i64;H],[0i64;H],[0i64;H]);let(mut count,mut time)=(0usize,0usize);
 loop{let mut active=false;let mut chosen=[-1i32;M];for q in 0..g.p{if pos[q]<g.plen[q]{active=true;let e=g.path[q][pos[q]];if chosen[e]<0{chosen[e]=q as i32}}}if !active{break}for e in 0..g.m{if chosen[e]>=0{if count>=H{return -1}tt[count]=time as i64;te[count]=e as i64;tp[count]=chosen[e] as i64;count+=1;pos[chosen[e] as usize]+=1}}time+=1;if time>N*P{return -1}}
 let nw=2+3*count;let bytes=nw*8;if output.is_null()||capacity<bytes{return -2}let mut words=[0i64;2+3*H];words[0]=time as i64;words[1]=count as i64;for i in 0..count{words[2+3*i]=tt[i];words[3+3*i]=te[i];words[4+3*i]=tp[i]}put(std::slice::from_raw_parts_mut(output,bytes),&words[..nw]);bytes as i64}
